// rankingHeaderLines is the height of the ranking header block: the header
// (wrapped at the inner width) + 1 blank, mirroring the Python header's
// `padding: 0 0 1 0`. The content table gets the rest of the inner height.
func (m *model) rankingHeaderLines(op, window string, total int) int {
	iw, _ := m.contentInner()
	return lipgloss.Height(rankingHeaderBlock(op, window, total, iw)) + 1
}

// rankingHeaderBlock is the ranking header wrapped to the inner width w, as
// Textual's height:auto header Static wraps in a narrow pane (one line when it
// fits, rendered exactly as before).
func rankingHeaderBlock(op, window string, total, w int) string {
	h := rankingHeader(op, window, total)
	if lipgloss.Width(h) > w {
		h = styled().Width(w).Render(h)
	}
	return h
}

// rankingHeader builds the "Operation: op  Window: win  (N runs)  <hints>" line,
// with bold op/window and dim hints (ports the Rich [b]/[dim] markup).
func rankingHeader(op, window string, total int) string {
	base := styled()
	b := base.Bold(true)
	d := base.Faint(true)
	return base.Render("Operation: ") + b.Render(op) +
		base.Render("  Window: ") + b.Render(window) +
		base.Render(fmt.Sprintf("  (%d runs)", total)) +
		d.Render("   ← prev op · next op →   press [ or ] to switch window")
}

// verifiedState resolves the current op, window label, and total runs for the
// verified pane (clamping indices defensively).
func (m *model) verifiedState() (op, window string, total int) {
	rd := m.data.fx.Verified
	if len(rd.Operations) == 0 {
		return "", cycleWindows[m.verifiedWinIdx], 0
	}
	op = rd.Operations[m.verifiedOpIdx%len(rd.Operations)]
	window = cycleWindows[m.verifiedWinIdx%len(cycleWindows)]
	for _, e := range rd.ByWindow[op][window] {
		total += e.Runs
	}
	return op, window, total
}

func (m *model) usageState() (op, window string, total int) {
	rd := m.data.fx.Usage
	if len(rd.Operations) == 0 {
		return "", cycleWindows[m.usageWinIdx], 0
	}
	op = rd.Operations[m.usageOpIdx%len(rd.Operations)]
	window = cycleWindows[m.usageWinIdx%len(cycleWindows)]
	for _, e := range rd.ByWindow[op][window] {
		total += e.Runs
	}
	return op, window, total
}

// buildVerifiedTable builds the verified ranking DataTable for the current
// op/window at the content-table size.
func buildVerifiedTable(m *model) datatable.Model {
	op, window, total := m.verifiedState()
	tw, th := m.contentTableSize(m.rankingHeaderLines(op, window, total))
	opts := []datatable.Option{
		datatable.WithColumn("Rank", "rank"),
		datatable.WithColumn("Model", "model"),
		datatable.WithColumn("Provider", "provider"),
		datatable.WithColumn("Score", "score"),
		datatable.WithColumn("Runs", "runs"),
		datatable.WithZebra(),
		datatable.WithSize(tw, th),
	}
	for i, e := range m.data.fx.Verified.ByWindow[op][window] {
		opts = append(opts, datatable.WithRow(strconv.Itoa(i),
			datatable.Text(strconv.Itoa(i+1)),
			datatable.Text(e.Model),
			datatable.Text(e.Provider),
			datatable.Text(strconv.Itoa(e.Score)),
			datatable.Text(strconv.Itoa(e.Runs)),
		))
	}
	return datatable.New(contentTableZoneID, opts...)
}

