func buildHeatmapTable(m *model) datatable.Model {
	fx := m.data.fx
	tw, th := m.contentTableSize(0)
	opts := []datatable.Option{
		datatable.WithCellCursor(), // labels.py: DataTable(zebra_stripes=True) → cursor_type="cell"
		datatable.WithColumn("Label", "label"),
		datatable.WithColumn("W-3", "w3"),
		datatable.WithColumn("W-2", "w2"),
		datatable.WithColumn("W-1", "w1"),
		datatable.WithColumn("W0", "w0"),
		datatable.WithZebra(),
		datatable.WithSize(tw, th),
	}
	for i, label := range fx.HeatmapLabels {
		if i >= len(fx.HeatmapRows) {
			break
		}
		r := fx.HeatmapRows[i]
		cells := []datatable.Cell{datatable.Text(label)}
		for _, v := range r {
			cells = append(cells, datatable.Text(strconv.Itoa(v)))
		}
		opts = append(opts, datatable.WithRow(label, cells...))
	}
	return datatable.New(contentTableZoneID, opts...)
}
